select.if:
select publisher, null finprodAbbr, null portFolioName, sum(marketValue) as marketValue, sum(dscCostAmt) as dscCostAmt, sum(shareAmt) as shareAmt, null marketValueRatio,
null portfolioId,'02' as hasChildren ,'root' parentInfo,publisher childInfo from (select gavInfo.publisher,gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(IFNULL(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select mci.customer_name publisher,psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId,psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join MST_CUSTOMER_INFO mci on (fp.ISSUER = mci.CUSTOMER_ID or (fp.MANAGER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F06') or (fp.FINANCIER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F18')) inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND mci.CUSTOMER_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,IFNULL(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and DATE_FORMAT(ppv.CDATE,'%Y-%m-%d')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 ) group by publisher

SELECT NULL publisher, finprodMarketId, finprodAbbr finprodAbbr, null portFolioName, sum(marketValue) marketValue, sum(dscCostAmt) dscCostAmt, sum(shareAmt) shareAmt, null marketValueRatio, null portfolioId, '01' AS hasChildren, publisher parentInfo, CONCAT(publisher,finprodMarketId) childInfo FROM (select gavInfo.publisher,gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(IFNULL(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select mci.customer_name publisher,psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId,psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join MST_CUSTOMER_INFO mci on (fp.ISSUER = mci.CUSTOMER_ID or (fp.MANAGER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F06') or (fp.FINANCIER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F18')) inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND mci.CUSTOMER_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,IFNULL(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and DATE_FORMAT(ppv.CDATE,'%Y-%m-%d')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 ) group by publisher,finprodMarketId,finprodAbbr union all SELECT NULL publisher, NULL finprodMarketId, NULL finprodAbbr, portFolioName, marketValue, dscCostAmt, shareAmt, marketValueRatio, portfolioId, '01' AS hasChildren, CONCAT(publisher,finprodMarketId) parentInfo, portFolioName childInfo FROM (select gavInfo.publisher,gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(IFNULL(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select mci.customer_name publisher,psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId,psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join MST_CUSTOMER_INFO mci on (fp.ISSUER = mci.CUSTOMER_ID or (fp.MANAGER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F06') or (fp.FINANCIER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F18')) inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND mci.CUSTOMER_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,IFNULL(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and DATE_FORMAT(ppv.CDATE,'%Y-%m-%d')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )

mapper.select:
select publisher,finprodMarketId,finprodAbbr,null portFolioName,sum(marketValue) as marketValue, sum(dscCostAmt) as dscCostAmt,sum(shareAmt) as shareAmt, round(sum(IFNULL(assetHold.marketValue,0))/sum(assetHold.tdyAssetValue)*100,2) as marketValueRatio,null portfolioId,'02' as hasChildren ,'root' parentInfo,finprodMarketId childInfo from (select gavInfo.publisher,gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(IFNULL(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select mci.customer_name publisher,psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId,psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join MST_CUSTOMER_INFO mci on (fp.ISSUER = mci.CUSTOMER_ID or (fp.MANAGER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F06') or (fp.FINANCIER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F18')) inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND mci.CUSTOMER_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,IFNULL(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and DATE_FORMAT(ppv.CDATE,'%Y-%m-%d')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )assetHold group by publisher,finprodMarketId,finprodAbbr union all select null publisher,null finprodMarketId,null finprodAbbr,portFolioName,marketValue,dscCostAmt,shareAmt, marketValueRatio,portfolioId,'01' as hasChildren ,finprodMarketId parentInfo,portFolioName childInfo from (select gavInfo.publisher,gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(IFNULL(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select mci.customer_name publisher,psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId,psv.SHARE_AMT shareAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*psv.DSC_COST_AMT when fpt.TYPE_6 = 'L02' then -1*psv.DSC_COST_AMT when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*psv.DSC_COST_AMT else psv.DSC_COST_AMT end as dscCostAmt, case when fpt.TYPE_8 = 'F08' AND fpt.TYPE_6 = 'L01' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_6 = 'L02' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) when fpt.TYPE_8 = 'F07' AND fpt.TYPE_7 = '03' then -1*(IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) else (IFNULL(psv.TDY_FLOAT_INGPL,0)+IFNULL(psv.DSC_COST_AMT,0)) end as marketValue, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID inner join MST_CUSTOMER_INFO mci on (fp.ISSUER = mci.CUSTOMER_ID or (fp.MANAGER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F06') or (fp.FINANCIER = mci.CUSTOMER_ID and fp.finprod_type2 = 'F18')) inner join FIN_PRODUCT_TYPE fpt on fpt.FINPROD_ID=psv.FINPROD_ID where 1=1
AND mci.CUSTOMER_ID IN
#{item}
and DATE_FORMAT(psv.CDATE,'%Y-%m-%d') = #{searchDate}
)gavInfo left join (select ppv.CDATE cdate,ppv.PORTFOLIO_ID portfolioId,IFNULL(ppv.TDY_ASSET_VALUE,0) tdyAssetValue from PTL_PORTFOLIO_VALUATION ppv where 1=1
and DATE_FORMAT(ppv.CDATE,'%Y-%m-%d')= #{searchDate}
)ppvInfo on ppvInfo.portfolioId=gavInfo.portfolioId and ppvInfo.cdate=gavInfo.cdate where ppvInfo.tdyAssetValue !=0 )assetHold
